from pathlib import Path
p = Path('public/app.js')
s = p.read_text()
s = s.replace("let DATA;\nconst state = { query: '', sort: 'rank', pillar: 'all' };", "let DATA;\nlet SKILLS;\nconst state = { query: '', sort: 'rank', pillar: 'all', skillQuery: '' };")
s = s.replace("const slugFromPath = () => decodeURIComponent(location.pathname.replace(/^\\/sectors\\/?/, '').replace(/\\/$/, ''));", "const slugFromPath = () => decodeURIComponent(location.pathname.replace(/^\\/sectors\\/?/, '').replace(/\\/$/, ''));\nconst skillSlugFromPath = () => decodeURIComponent(location.pathname.replace(/^\\/skills\\/?/, '').replace(/\\/$/, ''));")
s = s.replace('<a href="/sectors" data-route>Explore sectors</a><a href="/methodology" data-route>Methodology</a>', '<a href="/sectors" data-route>Explore sectors</a><a href="/skills" data-route>Skills archive</a><a href="/methodology" data-route>Methodology</a>')
s = s.replace('<a href="/data.json">JSON</a><a href="/content/full-dataset.md">Markdown</a><a href="/content/full-research-report.md">Full report</a><a href="/llms.txt">llms.txt</a>', '<a href="/data.json">JSON</a><a href="/skills.json">Skills JSON</a><a href="/connectors.json">Connectors</a><a href="/content/full-dataset.md">Markdown</a><a href="/content/full-research-report.md">Full report</a><a href="/llms.txt">llms.txt</a>')
marker = 'function methodology() {'
insert = r'''function skillCard(skill) {
  return `<a class="skill-card" href="/skills/${esc(skill.slug)}" data-route><div class="skill-card-top"><span class="skill-level">${esc(skill.level)}</span><span class="skill-category">${esc(skill.category)}</span></div><h3>${esc(skill.name)}</h3><p>${esc(skill.summary)}</p><div class="card-tags">${skill.capabilities.slice(0, 3).map(item => `<span class="tag">${esc(item)}</span>`).join('')}</div></a>`;
}
function filteredSkills() {
  const q = state.skillQuery.trim().toLowerCase();
  return SKILLS.skills.filter(skill => !q || JSON.stringify(skill).toLowerCase().includes(q));
}
function skillsHome() {
  const skills = filteredSkills();
  return `<main id="main"><section class="hero skills-hero"><div><div class="eyebrow">AI skills archive / derived from free public sources</div><h1>Give agents<br><em>better habits.</em></h1><p class="hero-deck">A curated library of portable workflows built from free courses and open documentation. Each skill keeps its provenance, use cases, safety notes, and machine-readable source record.</p></div><aside class="hero-aside"><strong>${SKILLS.skills.length} skills</strong><p>Public knowledge is archived here. Secret API-key values are never stored in the archive.</p></aside></section><div class="search-band"><div class="search-top"><h2>Search the skills archive</h2><a href="/skills.json">Skills JSON ↗</a></div><div class="search-row skills-search-row"><label class="search-wrap"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="11" cy="11" r="7"></circle><path d="m20 20-4-4"></path></svg><input class="search-input" data-skill-search type="search" placeholder="Search skills, capabilities, sources…" value="${esc(state.skillQuery)}" aria-label="Search the AI skills archive" /></label></div><p class="search-note">Derived skills summarize public material and link back to the original course or documentation. They do not reproduce source lessons wholesale.</p></div><section class="section-head"><div><div class="section-kicker">Portable workflows</div><h2>Skills for an agent’s working memory</h2></div><p>${skills.length} skill${skills.length === 1 ? '' : 's'} in view. Open one to inspect its workflow, provenance, connectors, and downloadable SKILL.md.</p></section><div class="skill-grid">${skills.length ? skills.map(skillCard).join('') : '<div class="empty">No skills match that search.</div>'}</div><section class="connector-callout"><div><div class="section-kicker">Credentials stay separate</div><h2>Keys are not skills.</h2><p>20/20 archives connector requirements and credential names such as <code>PROVIDER_API_KEY</code>. The actual secret value belongs in a protected server-side vault or environment—not in a public skill file.</p></div><a class="download-link" href="/connectors.json">Open connector catalog ↗</a></section></main>${footer()}`;
}
function skillDetail(skill) {
  const sources = skill.sources.map(source => `<li><a href="${safeUrl(source.url)}" target="_blank" rel="noopener">${esc(source.title)} ↗</a><span>${esc(source.license)}</span></li>`).join('');
  return `<main id="main"><div class="breadcrumb"><a href="/skills" data-route>Skills archive</a><span>→</span><span>${esc(skill.name)}</span></div><section class="detail-hero"><div><div class="section-kicker">${esc(skill.category)} / ${esc(skill.level)}</div><h1>${esc(skill.name)}</h1><p class="detail-deck">${esc(skill.summary)}</p></div><div class="rank-stamp skill-stamp"><div class="stamp-rank">SK</div><div class="stamp-label">portable skill</div><div class="stamp-score">${skill.workflow.length} steps</div></div></section><div class="detail-layout skill-detail-layout"><article class="detail-copy"><h2>Use this skill when</h2><ul class="list-clean">${skill.uses.map(item => `<li>${esc(item)}</li>`).join('')}</ul><h3>Capabilities</h3><div class="capability-list">${skill.capabilities.map(item => `<span class="tag">${esc(item)}</span>`).join('')}</div><h3>Workflow</h3><ol class="workflow-list">${skill.workflow.map(item => `<li>${esc(item)}</li>`).join('')}</ol><h3>Archive note</h3><div class="score-key">${esc(skill.archiveNote)}</div></article><aside class="detail-side"><div class="side-panel"><h3>Machine access</h3><a class="download-link" href="/content/skills/${esc(skill.slug)}.md">Download SKILL.md ↗</a><a class="download-link" href="/skills.json">Use full skills JSON ↗</a></div><div class="side-panel"><h3>Connector references</h3><ul class="list-clean">${skill.connectors.length ? skill.connectors.map(item => `<li><code>${esc(item)}</code></li>`).join('') : '<li>This skill does not require a connector.</li>'}</ul></div><div class="side-panel source-list"><h3>Provenance</h3><p class="source-count">${skill.sources.length} public source${skill.sources.length === 1 ? '' : 's'}.</p><ul class="list-clean">${sources}</ul></div></aside></div></main>${footer()}`;
}
'''
s = s.replace(marker, insert + marker)
s = s.replace("if (!DATA) { app.innerHTML = '<div class=\"loading\">Loading the research universe…</div>'; return; }", "if (!DATA || !SKILLS) { app.innerHTML = '<div class=\"loading\">Loading the research universe…</div>'; return; }")
s = s.replace("if (path === '/methodology') body = methodology();\n  else if (path.startsWith('/sectors/') && slugFromPath()) {", "if (path === '/methodology') body = methodology();\n  else if (path === '/skills') body = skillsHome();\n  else if (path.startsWith('/skills/') && skillSlugFromPath()) {\n    const skill = SKILLS.skills.find(item => item.slug === skillSlugFromPath());\n    body = skill ? skillDetail(skill) : skillsHome();\n  }\n  else if (path.startsWith('/sectors/') && slugFromPath()) {")
s = s.replace("document.title = path.startsWith('/sectors/') ? `${DATA.sectors.find(item => item.slug === slugFromPath())?.name || 'Sector'} — 20/20` : path === '/methodology' ? 'Methodology — 20/20' : '20/20 — Data Refinery';", "document.title = path.startsWith('/sectors/') ? `${DATA.sectors.find(item => item.slug === slugFromPath())?.name || 'Sector'} — 20/20` : path.startsWith('/skills/') ? `${SKILLS.skills.find(item => item.slug === skillSlugFromPath())?.name || 'Skill'} — 20/20` : path === '/skills' ? 'AI Skills Archive — 20/20' : path === '/methodology' ? 'Methodology — 20/20' : '20/20 — Data Refinery';")
s = s.replace("document.querySelector('[data-pillar]')?.addEventListener('change', event => { state.pillar = event.target.value; render(); });", "document.querySelector('[data-pillar]')?.addEventListener('change', event => { state.pillar = event.target.value; render(); });\n  const skillInput = document.querySelector('[data-skill-search]');\n  if (skillInput) skillInput.addEventListener('input', event => { state.skillQuery = event.target.value; render(); const next = document.querySelector('[data-skill-search]'); next?.focus(); next?.setSelectionRange(state.skillQuery.length, state.skillQuery.length); });")
s = s.replace("fetch('/data.json').then(response => response.json()).then(data => { DATA = data; render(); }).catch(() => {", "Promise.all([fetch('/data.json').then(response => response.json()), fetch('/skills.json').then(response => response.json())]).then(([data, skills]) => { DATA = data; SKILLS = skills; render(); }).catch(() => {")
p.write_text(s)
print('patched app.js')
